(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.022-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.03-t*0.4)*6 + Math.cos(sy*0.025+t*0.35)*4;
  const w2y = Math.cos(sy*0.028+t*0.38)*6 + Math.sin(sx*0.022-t*0.42)*4;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*60, 0.07, 2.1, 1.0],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*60, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*100, 0.055, 2.4, 1.1],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*70, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*100, 55+Math.cos(t*0.8+2)*80, 0.065, 2.7, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*90, 0.085, 2.0, 0.95],
    [60+Math.sin(t*0.6+3)*70, 120+Math.cos(t*0.75+1)*80, 0.1, 1.9, 0.8],
    [420+Math.cos(t*0.48+2)*60, 180+Math.sin(t*0.65+4)*50, 0.075, 2.2, 1.0]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const d2 = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.55+1.5)*w;
    aS2 += Math.sin(d2*f*1.3-t*sp*0.8+2.0)*w*0.5;
    iS2 += Math.cos(d2*f*0.9+t*sp*0.4)*w*0.5;
  }
  const n = src.length;
  const act = (aS+aS2*0.4)/(n*1.4), inh = (iS+iS2*0.4)/(n*1.4);
  const bg1 = (Math.sin(fx*0.035+fy*0.022+t*0.7)+Math.sin(fx*0.028-fy*0.038+t*1.0))/2;
  const bg2 = Math.sin((fx+fy)*0.1+t*2.2)*0.25+Math.sin((fx-fy)*0.08-t*1.8)*0.25;
  const bg3 = Math.sin(fx*0.06+fy*0.04+t*1.5)*Math.cos(fx*0.04-fy*0.06-t*1.2)*0.3;
  const bg = bg1+bg2+bg3;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.038+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2+t*2.0)*0.5;
  const spiral = (sp1+sp2)*0.35+sp3;
  const lap = (Math.sin(fx*0.12)*Math.sin(fy*0.12)+Math.sin((fx+fy)*0.09+t*0.8)*0.4+Math.sin((fx-fy)*0.07-t*1.2)*0.3);
  const diffusion = Math.tanh(lap*1.8)*0.25;
  let r1 = act-inh*0.65+bg*0.25+spiral*0.35+diffusion;
  const r2 = Math.sin(r1*2.8+t*0.3)*0.15+Math.cos(r1*1.5-t*0.5)*0.1;
  r1 += r2;
  const reaction = Math.tanh(r1*2.0);
  const cell = Math.tanh((Math.sin(fx*0.13)*Math.sin(fy*0.13)+Math.sin((fx+fy)*0.09+t)*0.45)*1.6)*0.2;
  const micro = Math.sin(fx*0.25+t*3)*Math.sin(fy*0.25-t*2.5)*0.08;
  const blend = reaction*0.65+cell*0.2+micro;
  const v = blend*0.5+0.5;
  const edge = Math.abs(reaction);
  const glow = Math.exp(-edge*2.5)*0.4;
  const vf = Math.min(1, v+glow*0.3);
  const pal = [
    [6,12,52],[10,35,85],[14,65,115],[18,105,130],
    [35,150,135],[90,175,110],[170,185,70],[210,195,55],
    [220,150,60],[215,105,65],[185,65,70],[140,40,75],
    [95,25,65],[55,18,58],[25,12,50],[6,12,52]
  ];
  const idx = vf*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const sm = 0.7+f*(1-f)*0.6;
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const eBoost = edge>0.72?1.12+glow*0.3:1.0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*eBoost)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*eBoost)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*eBoost)|0
  ];
}
